mod=7;n=23
M=[[0]*n for _ in range(n)]
for i in range(n):
    M[i][(i-1)%n]=5; M[i][i]=2; M[i][(i+1)%n]=3

def mat_mul(A,B):
    n=len(A); m=len(B[0]); p=len(B)
    C=[[0]*m for _ in range(n)]
    for i in range(n):
        Ai=A[i]
        Ci=C[i]
        for k in range(p):
            aik=Ai[k]
            if aik:
                Bk=B[k]
                for j in range(m):
                    Ci[j]=(Ci[j]+aik*Bk[j])%mod
    return C

def mat_vec_mul(A,v):
    return [sum(A[i][k]*v[k] for k in range(n))%mod for i in range(n)]

def mat_pow(M,e):
    R=[[1 if i==j else 0 for j in range(n)] for i in range(n)]
    A=[row[:] for row in M]
    while e:
        if e&1:
            R=mat_mul(R,A)
        A=mat_mul(A,A)
        e//=2
    return R

def step_state(s):
    return ''.join(rule[s[(i-1)%n]+s[i]+s[(i+1)%n]] for i in range(n))

