letters='ABCDEFG'
num={'A':0,'B':1,'C':6,'D':2,'E':3,'F':4,'G':5}
inv={v:k for k,v in num.items()}
start=open('start.txt').read().strip()
# y'_i = 5 y_{i-1}+2 y_i+3 y_{i+1}; in polynomial form coeff at x^i; multiplication by p=2+3x+5x^-1 = 2+3x+5x^22
p=[0]*n
p[0]=2; p[1]=3; p[-1]=5

def conv(a,b):
    c=[0]*n
    for i,ai in enumerate(a):
        if ai:
            for j,bj in enumerate(b):
                if bj:
                    c[(i+j)%n]=(c[(i+j)%n]+ai*bj)%mod
    return c

def pow_apply(poly,e,vec):
    # apply poly^e by exponentiating and convolving with vec
    base=poly[:]
    res=[0]*n; res[0]=1
    while e:
        if e&1:
            res=conv(res,base)
        base=conv(base,base)
        e//=2
    return conv(res,vec)

